};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid1_OnDblClick
 * @description grd_Grid1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid1_OnDblClick = async function(row, colid) {
    try {
        await scwin.read(grd_Grid1, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30606.grd_Grid1_OnDblClick" });
    }
};

