/**
 * @method
 * @name grd_Grid3_OnDblClick
 * @description grd_Grid3 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid3_OnDblClick = async function(row, colid) {
    try {
        if (colid === "ACPT_NO") {
            const AcptNo = dts_Grid3.getCellData(row, "ACPT_NO");
            await $c.stf.openDisclViewer(AcptNo, "R");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30606.grd_Grid3_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let vISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD");
    const vCOM_NM = $c.stf.getQuery(frame.srcUrl, "COM_NM");
    const vSTKCERT_LIST_DD = $c.stf.getQuery(frame.srcUrl, "STKCERT_LIST_DD");
    txb_ISUR_CD.setValue(vISUR_CD);
    txb_COM_NM.setValue(vCOM_NM);
    txb_STKCERT_LIST_DD.setValue(vSTKCERT_LIST_DD);
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCREN_ID=" + "ULDSTF30606.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid1",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCREN_ID=" + "ULDSTF30606.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_Grid2",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCREN_ID=" + "ULDSTF30606.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions3 = {
        id : "sbm_dts_Grid3",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

