 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name read
 * @description 작업해야함
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function(GridID, row, colid) {
    // 작업해야함
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    let CMD = "R";
    if (row < 1) return;

    // OPEN
    if (colid === "REMINDER_YN") {
        // 상세화면
        let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        let vEDU_KIND_CD = objDataID.getCellData(row, "EDU_KIND_CD");
        const vEDU_KIND_CDNM = objDataID.getCellData(row, "EDU_KIND_CDNM");
        const vREMINDER_YN = objDataID.getCellData(row, "REMINDER_YN");
        const vEDU_PARTC_ID = objDataID.getCellData(row, "EDU_PARTC_ID");
        if (js_market === '6') vEDU_KIND_CD = '81';
        let CMD = "R";
        if (vREMINDER_YN !== '') {
            if (await scwin.setParam(CMD, vISUR_CD, vEDU_KIND_CD, vEDU_KIND_CDNM, vEDU_PARTC_ID)) // formal arguments

            {
                const options = {
                    id: "ULDSTF30609",
                    title: "세부교육이수현황",
                    type: "browserPopup",
                    width: "450px",
                    height: "190px",
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("/issueinfo/ULDSTF30609.gfm", options);
            }
        }
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
